<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount} from 'vue';
import type {Trace,Table} from '../api';import type {Frame} from '../animation/timeline';import {ease,phase} from '../animation/timeline';import ResultTable from './ResultTable.vue';
const props=defineProps<{trace:Trace,frame:Frame,progress:number,reduced:boolean,inspection?:string}>();
const emit=defineEmits<{inspect:[string]}>();const host=ref<HTMLElement>();const width=ref(600);let observer:ResizeObserver|undefined;
onMounted(()=>{observer=new ResizeObserver(entries=>width.value=entries[0].contentRect.width);observer.observe(host.value!)});onBeforeUnmount(()=>observer?.disconnect());
const step=computed(()=>props.trace.steps[props.frame.stepIndex]);
const inputs=computed(()=>{const s=step.value;return s.details.length?s.details.map((table,i)=>({id:`s${s.id}:d${i}`,table,title:s.details.length===2?(i?'右侧输入':'左侧输入'):'冻结输入'})):s.parents.map(id=>props.trace.steps.find(s=>s.id===id)).filter(s=>!!s).map(s=>({id:`s${s.id}`,table:s.table,title:s.title}));});
const inspectEvent=computed(()=>props.inspection===undefined?undefined:step.value.events.find(e=>e.id===props.inspection));
const event=computed(()=>inspectEvent.value??props.frame);
function inspect(table:string,index:number){const e=step.value.events.find(e=>[...e.sources,...e.targets].some(r=>r.table===table&&r.index===index));if(e)emit('inspect',e.id)}
const active=(id:string)=>event.value.sources.filter(r=>r.table===id).map(r=>r.index);
const inputColumns=(table:Table)=>event.value.truth?event.value.columns:table.columns.flatMap((c,i)=>step.value.table.columns.includes(c)?[i]:[]);
const targets=computed(()=>event.value.targets.map(r=>r.index));
const tone=computed(()=>event.value.truth==='UNKNOWN'?'unknown':event.value.kind==='drop'?'drop':'keep');
const movement=computed(()=>ease(Math.max(0,Math.min(1,(props.progress-.15)/.4))));
const cards=computed(()=>{const refs=event.value.sources.length?event.value.sources.slice(0,2):event.value.targets.slice(0,1);return refs.map(r=>{const table:Table|undefined=inputs.value.find(t=>t.id===r.table)?.table??step.value.table;return{label:`#${r.index+1}`,value:table?.rows[r.index]?.slice(0,3).map(c=>'value'in c?String(c.value):'NULL').join(' · ')??'空关系'};});});
</script>
<template><section ref="host" class="animation-stage" :class="[tone,{'reduced-motion':reduced}]" :data-phase="phase(progress)" :data-event="frame.id"><div class="stage-caption"><b>{{event.message}}</b><span class="certainty" :class="event.certainty">{{event.certainty==='exact'?'✓ 已验证事件':event.certainty==='occurrence'?'↔ 冻结记录对应':'≈ 来源候选'}}</span></div><div class="flow-track" aria-label="记录流向"><span class="track-label">输入记录</span><div class="track-line"><span>{{event.truth??(frame.batch?`${frame.batch} 条合批`:step.kind)}}</span></div><span class="track-label">{{tone==='drop'?'筛除区':'输出关系'}}</span><div v-for="(card,i) in cards" :key="i" class="flying-record" :class="{candidate:event.certainty==='candidate'}" :style="{transform:`translate3d(${reduced?(progress>=.55?width-194:12):12+movement*Math.max(0,width-206)}px,${i*27}px,0)`,opacity:progress>=.94?.3:1}"><strong>{{card.label}}</strong><span>{{card.value}}</span></div><span v-if="!cards.length" class="empty-flow">∅ 空关系</span></div><p v-if="event.certainty==='candidate'" class="candidate-note">虚线表示候选关联；没有把重复值或未确认的来源画成唯一匹配；每侧最多高亮 24 个候选。</p><div class="animation-tables"><div class="input-relations"><ResultTable v-for="input in inputs" :key="input.id" :table="input.table" :title="input.title" :highlight-rows="active(input.id)" :highlight-columns="inputColumns(input.table)" :tone="progress<.55?'active':tone" teaching compact @row-select="inspect(input.id,$event)"/><div v-if="!inputs.length" class="source-card">▤ 读取冻结快照<br><small>记录编号只在本次快照内有效。</small></div></div><div><ResultTable :table="step.table" title="冻结输出 · 高亮当前演示记录" :highlight-rows="targets" :highlight-columns="event.columns" :tone="progress>=.55?'keep':'active'" teaching compact @row-select="inspect(`s${step.id}`,$event)"/></div></div></section></template>
